# EU results: every EU query returned zero ads (NL for all 7, DE for RS as a
# second EU probe). Recorded here for the report / provenance.
EU_RESULTS = {
    "1582026298728590": {"NL": 0, "DE": 0},
    "471114526327906": {"NL": 0},
    "175590904720": {"NL": 0},
    "172343479474457": {"NL": 0},
    "1881955151887046": {"NL": 0},
    "116918619388": {"NL": 0},
    "151841294689427": {"NL": 0},
}


def parse_payload(blob):
    """Double-decode a {"results": "<json string>"} tool payload -> dict."""
    outer = json.loads(blob)
    return json.loads(outer["results"])


def iso(ts):
    if not ts:
        return ""
    return datetime.datetime.utcfromtimestamp(int(ts)).strftime("%Y-%m-%d")


def main():
    out_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "output")
    os.makedirs(out_dir, exist_ok=True)
    csv_path = os.path.join(out_dir, "countertop_ads_creative.csv")
    full_path = os.path.join(out_dir, "countertop_ads_full.csv")
    report_path = os.path.join(out_dir, "countertop_ads_report.json")

    rows = []       # the 8-column task CSV
    full_rows = []  # every field available, one row per ad
    report = []
    totals = {"ads": 0, "with_body": 0, "empty_body": 0, "with_link_title": 0}

    for (name, pid), blob in US_RAW.items():
        payload = parse_payload(blob)
        ads = payload.get("ads", [])
        est = payload.get("estimated_total_count", len(ads))
        # guard against a truncated copy/paste of the embedded blob
        assert len(ads) == est, f"{name}: parsed {len(ads)} ads but estimated_total_count={est}"

        eu = EU_RESULTS.get(pid, {})
        eu_total = sum(eu.values())

        for ad in ads:
            link_title = (ad.get("ad_creative_link_title") or "").strip()
            body_text = ""  # ad_creative_bodies not exposed for these US ads (EU-only field; 0 EU ads)
            row = {
                "advertiser": name,
                "page_id": pid,
                "ad_id": str(ad.get("id", "")),
                "body_text": body_text,
                "link_title": link_title,
                "snapshot_url": ad.get("ad_snapshot_url", ""),
                "delivery_start": iso(ad.get("ad_delivery_start_time")),
                # provenance + body presence; body is empty for every US-reached ad
                "status": "US/empty",
            }
            rows.append(row)

            full_rows.append({
                "advertiser": name,
                "page_id": pid,
                "page_name": ad.get("page_name", ""),
                "ad_id": str(ad.get("id", "")),
                "ad_creation_time": iso(ad.get("ad_creation_time")),
                "ad_delivery_start_time": iso(ad.get("ad_delivery_start_time")),
                "currency": ad.get("currency", ""),
                "reached_country": "US",
                "body_text": body_text,                 # empty: EU-only field, 0 EU ads
                "link_title": link_title,
                "link_caption": "",                     # not returned by FB MCP tool
                "link_description": "",                  # not returned by FB MCP tool
                "publisher_platforms": "",              # not returned by FB MCP tool
                "ad_snapshot_url": ad.get("ad_snapshot_url", ""),
                "eu_ads_found": eu_total,
                "status": "US/empty",
            })

            totals["ads"] += 1
            totals["empty_body"] += 1
            if link_title:
                totals["with_link_title"] += 1

        report.append({
            "advertiser": name,
            "page_id": pid,
            "us_ads": len(ads),
            "us_with_body": 0,
            "us_with_link_title": sum(1 for a in ads if (a.get("ad_creative_link_title") or "").strip()),
            "eu_queries": eu,
            "eu_ads_total": eu_total,
        })

    fieldnames = [
        "advertiser", "page_id", "ad_id", "body_text",
        "link_title", "snapshot_url", "delivery_start", "status",
    ]
    with open(csv_path, "w", newline="", encoding="utf-8") as fh:
        w = csv.DictWriter(fh, fieldnames=fieldnames)
        w.writeheader()
        w.writerows(rows)

    full_fieldnames = [
        "advertiser", "page_id", "page_name", "ad_id",
        "ad_creation_time", "ad_delivery_start_time", "currency", "reached_country",
        "body_text", "link_title", "link_caption", "link_description",
        "publisher_platforms", "ad_snapshot_url", "eu_ads_found", "status",
    ]
    with open(full_path, "w", newline="", encoding="utf-8") as fh:
        w = csv.DictWriter(fh, fieldnames=full_fieldnames)
        w.writeheader()
        w.writerows(full_rows)

    with open(report_path, "w", encoding="utf-8") as fh:
        json.dump({
            "source": "mcp__FB__ads_library_search (live Meta Ad Library)",
            "advertisers": report,
            "totals": totals,
            "note": (
                "ad_creative_bodies is an EU-only field and every EU query returned 0 ads, "
                "so no ad has real body text via the API. link_title carries the headline; "
                "the full visual creative is at each ad_snapshot_url."
            ),
        }, fh, indent=2)

    print("Wrote {} ad rows -> {}".format(len(rows), csv_path))
    print("Wrote {} ad rows (all fields) -> {}".format(len(full_rows), full_path))
    print("Report -> {}".format(report_path))
    print("-" * 56)
    for r in report:
        print("{:<32} US ads: {:>2}   link-titles: {:>2}   EU ads: {}".format(
            r["advertiser"], r["us_ads"], r["us_with_link_title"], r["eu_ads_total"]))
    print("-" * 56)
    print("TOTAL ads:            {}".format(totals["ads"]))
    print("  with real body:     {}".format(totals["with_body"]))
    print("  empty body:         {}".format(totals["empty_body"]))
    print("  (with link title):  {}".format(totals["with_link_title"]))


if __name__ == "__main__":
    main()
